[{'file': 'src/core/parser.py', 'type': 'modified', 'added_lines': ['#parser', '# parser.py', 'from unidiff import PatchSet', 'from typing import List, Dict, Any', 'import os', '', 'def parse_git_diff(diff_text: str) -> List[Dict[str, Any]]:', '    """', '    Parse a git diff string into structured file changes.', '    ', '    Args:', '        diff_text (str): Output of `git diff` or `git diff --cached`', '        ', '    Returns:', '        List[Dict]: List of file-level structured diffs', '    """', '    patch = PatchSet(diff_text.splitlines())', '    files = []', '', '    for patched_file in patch:', '        file_change = {', '            "file": patched_file.path,', '            "type": "added" if patched_file.is_added_file else', '                    "deleted" if patched_file.is_removed_file else', '                    "modified",', '            "added_lines": [],', '            "removed_lines": [],', '            "meta": {', '                "insertions": patched_file.added,', '                "deletions": patched_file.removed', '            }', '        }', '', '        for hunk in patched_file:', '            for line in hunk:', '                # Only parse added/removed lines', '                if line.is_added:', '                    file_change["added_lines"].append(line.value.rstrip("\\n"))', '                elif line.is_removed:', '                    file_change["removed_lines"].append(line.value.rstrip("\\n"))', '', '        files.append(file_change)', '', '    return files', '', '', '# Example usage', 'if __name__ == "__main__":', '    # Get diff from staged files', '    diff_text = os.popen("git diff --cached").read()', '    parsed_files = parse_git_diff(diff_text)', '    for f in parsed_files:', '        print(f)'], 'removed_lines': ['# unidiff logic'], 'meta': {'insertions': 53, 'deletions': 1}}, {'file': 'src/core/prompt.py', 'type': 'added', 'added_lines': ['# prompt builder', 'import json', '', 'def build_system_prompt():', '    # Sets Who the AI is (The persona). This sets behavior and personality.', '    return """You are an expert software engineer.', '', 'You write clear, concise, and meaningful Git commit messages based on structured code changes.', '', 'You focus on:', '- Understanding developer intent', '- Summarizing changes at a high level', '- Avoiding low-level or redundant details', '', 'Best practices:', '- Use present tense', '- Be specific and direct', '- Avoid vague messages like "update code"', '- Do not explain the commit message', '- Output only the commit message', '"""', '', 'def build_addons(schema):', '    #Dynamic context. Injected based on schema signals. These act as soft guidance, not strict rules.', '    addons = []', '', '    files_changed = schema.get("meta", {}).get("files_changed", 0)', '    hints = schema.get("hints", {})', '', '    if files_changed > 5:', '        addons.append(', '            "Note: This is a large set of changes. Focus on summarizing the overall intent."', '        )', '', '    if hints.get("breaking_change"):', '        addons.append(', '            "Note: This change introduces breaking behavior. Make it explicit."', '        )', '', '    if hints.get("suggested_type") == "test":', '        addons.append(', '            "Note: These changes primarily affect tests."', '        )', '', '    if hints.get("suggested_type") == "refactor":', '        addons.append(', '            "Note: These changes refactor existing code without changing behavior."', '        )', '', '    return "\\n".join(addons)', '', 'def build_user_prompt(schema, config:dict):', '    #This is the final user dynamic prompt that is sent to the LLM for inference. It defines task + context specific data', '    ', '    schema_json = json.dumps(schema, indent=2)', '', '    base_prompt = ""', '', '    if config.get("style") == "conventional":', '        base_prompt = f"""', '        Generate a git commit message from the structured changes below.', '', '        Rules:', '        - Format: <type>(<scope>): <message>', '        - Title must be under {config.get("max_title_length", 72)} characters', '        - Use the suggested type and scope if appropriate, but correct them if wrong', '        - Focus on WHAT changed and WHY, not implementation details', '        - Keep it concise but meaningful', '        """', '', '        if config.get("include_body", True):', '            base_prompt += """', '            Optional:', '            - Include a short body (1–3 bullet points) if the change is non-trivial', '            """', '', '        base_prompt += """', '        Special cases:', '        - If the change is breaking, add "!" after the type', '        - Prioritize the most significant change if multiple exist', '        """', '', '    else:', '        base_prompt = """', '        Generate a concise and meaningful git commit message.', '', '        Rules:', '        - Do NOT use prefixes like feat:, fix:, etc.', '        - Keep it short and clear', '        - Focus on intent, not implementation details', '        """', '', '    # Add dynamic intelligence/Context', '    addons = build_addons(schema)', '', '    # Add custom user instructions', '    custom = config.get("custom_instructions", "")', '', '    final_prompt = f"""', '    {base_prompt}', '', '    Structured data:', '    {schema_json}', '    """', '', '    if addons:', '        final_prompt += f"\\n{addons}\\n"', '', '    if custom:', '        final_prompt += f"\\nAdditional instructions:\\n{custom}\\n"', '', '    return final_prompt.strip()'], 'removed_lines': [], 'meta': {'insertions': 112, 'deletions': 0}}]